import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA source: naive half‑precision GEMM C = A @ B.T
#   A : (M, K)  half
#   B : (N, K)  half   (stored as N rows, K cols)
#   C : (M, N)  half   C[i,j] = sum_k A[i,k] * B[j,k]
# Accumulate in float for accuracy.
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>

#ifndef CHECK_CUDA
#define CHECK_CUDA(x) TORCH_CHECK(x.is_cuda(), #x " must be a CUDA tensor")
#endif
#ifndef CHECK_CONTIGUOUS
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#endif
#ifndef CHECK_INPUT
#define CHECK_INPUT(x) CHECK_CUDA(x); CHECK_CONTIGUOUS(x)
#endif

// ------------------------------------------------------------------
// Kernel: one thread per output element
// ------------------------------------------------------------------
__global__ void matmul_fp16_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int M, int N, int K)
{
    int row = blockIdx.y * blockDim.y + threadIdx.y; // M dimension
    int col = blockIdx.x * blockDim.x + threadIdx.x; // N dimension

    if (row >= M || col >= N) return;

    float acc = 0.0f;
    // compute dot product of A[row, :] and B[col, :] (since B is stored as N×K)
    for (int k = 0; k < K; ++k) {
        float a = __half2float(A[row * K + k]);
        float b = __half2float(B[col * K + k]);   // B[col, k]
        acc += a * b;
    }
    C[row * N + col] = __float2half(acc);
}

// ------------------------------------------------------------------
// PyTorch binding
// ------------------------------------------------------------------
torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    CHECK_INPUT(A);
    CHECK_INPUT(B);
    TORCH_CHECK(A.dtype() == torch::kFloat16, "A must be half precision");
    TORCH_CHECK(B.dtype() == torch::kFloat16, "B must be half precision");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2‑D");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    TORCH_CHECK(B.size(1) == K, "Inner dimensions must match");
    int64_t N = B.size(0);   // B is (N, K)

    auto C = torch::empty({M, N}, A.options());

    const dim3 block(16, 16);
    const dim3 grid( (N + block.x - 1) / block.x,
                     (M + block.y - 1) / block.y );

    matmul_fp16_kernel<<<grid, block, 0,
        c10::cuda::getCurrentCUDAStream()>>>(
            reinterpret_cast<const __half*>(A.data_ptr<at::Half>()),
            reinterpret_cast<const __half*>(B.data_ptr<at::Half>()),
            reinterpret_cast<__half*>(C.data_ptr<at::Half>()),
            static_cast<int>(M),
            static_cast<int>(N),
            static_cast<int>(K));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch error: ", cudaGetErrorString(err));
    }
    return C;
}
'''

cpp_declaration = "torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B);"

# Compile the inline extension
matmul_ext = load_inline(
    name="matmul_fp16_ext",
    cpp_sources=cpp_declaration,
    cuda_sources=cuda_source,
    functions=["matmul_fp16"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Half‑precision matrix multiplication: C = A @ B.T
    - A : (M, K) torch.float16 CUDA tensor
    - B : (N, K) torch.float16 CUDA tensor
    Returns:
    - C : (M, N) torch.float16 CUDA tensor
    """
    def __init__(self):
        super().__init__()
        self._impl = matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure correct dtype / device / contiguity
        if A.dtype != torch.float16:
            A = A.to(dtype=torch.float16)
        if B.dtype != torch.float16:
            B = B.to(dtype=torch.float16)
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        if not A.is_contiguous():
            A = A.contiguous()
        if not B.is_contiguous():
            B = B.contiguous()
        return self._impl.matmul_fp16(A, B)
